add(1993,2,1,6.5,'Geometry',r'Choose $D,E,F$ in the interiors of sides $BC,CA,AB$ of triangle $ABC$. Consider its three vertex angles and the nine angles $\angle BDF,\angle FDE,\angle EDC$, $\angle CED,\angle DEF,\angle FEA$, $\angle AFE,\angle EFD,\angle DFB$. Suppose all twelve are distinct positive integer multiples of the same angular unit. Find the smallest possible sum of the three vertex angles in that unit, and give a corresponding assignment of the twelve angles.','A sum bound on twelve distinct integer angles is only the start; the sharp assignment must also be geometrically realisable as an inscribed triangle.',None,['Angle sums','Extremal configurations','Integer constraints'])
add(1995,1,2,4.5,'Geometry',r'A cube of side $2$ has top face $ABCD$ and bottom face $FGHE$, with vertical edges $AF,BG,CH,DE$. Let $M,N$ be the midpoints of $BC,EF$. (a) Find the area of quadrilateral $AMHN$. (b) Let $P,Q$ be the midpoints of $AB,HE$, and put $X=AM\cap CP$, $Y=HN\cap FQ$. Find $XY$.','The section is a non-rectangular parallelogram, and the second part requires two planar intersection ratios before a spatial distance calculation.',r'Use coordinates $A=(0,0,2),B=(2,0,2),C=(2,2,2),D=(0,2,2)$ and $F=(0,0,0),G=(2,0,0),H=(2,2,0),E=(0,2,0)$. Then $M=(2,1,2)$ and $N=(0,1,0)$. The parallelogram has adjacent vectors $(2,1,0)$ and $(0,1,-2)$, whose cross product has length $2\sqrt6$, its area. The intersections are $X=(4/3,2/3,2)$ and $Y=(2/3,4/3,0)$, obtained by solving the two line equations on the top and bottom faces. Hence $XY=\sqrt{4/9+4/9+4}=2\sqrt{11}/3$.',['Solid geometry','Vectors','Coordinate geometry'])
