 payload={'source':'https://bmos.ukmt.org.uk/home/bmo.shtml','solutionIndex':'https://bmos.ukmt.org.uk/solutions/','fullyScreenedRange':'BMO1 and BMO2, archive seasons 1992–2026 inclusive','papers':papers,'screening':sorted(screening,key=lambda s:(s['year'],s['round'],s['number'])),'counts':{'papersFullyScreened':sum(p['status']=='fully-screened' for p in papers),'included':len(records),'assessed':sum(s['difficulty'] is not None for s in screening),'excluded':sum(s['decision']=='exclude' for s in screening),'pending':sum(s['decision']=='pending' for s in screening),'withOwnWorkedSolution':sum(bool(r['solution']) for r in records),'withOfficialSolutionLink':sum(bool(r['solutionUrl']) for r in records)},'gaps':[{'range':'BMO 1973–1991 and FIST 1972–1991','status':'historical extension in progress','detail':'Official archive links located. These historical predecessor papers are separate from the fully screened BMO1/BMO2 range.'},{'range':'BMO 1965–1972; FIST 1973','status':'not available as papers in official archive','detail':'Official archive notes unavailable papers and points to historical books.'},{'range':'Solutions outside linked public video/written ranges','status':'partial','detail':'Own worked exposition included only where verified. Commercial-book solutions have not been copied. Missing solutions remain explicitly absent.'}],'method':'Every decision was individually authored after reading the specific official problem and analysing its mathematical structure. Difficulty is a subjective AI estimate, not an official UKMT score; it is not inferred from question position. Some solutions were worked through directly; official linked videos/PDFs are identified as available resources, not claimed fully transcribed or individually watched.','yearConvention':'The year field follows official archive filenames. From BMO1-2002 onward, BMO1 was sat in the preceding calendar year and its season is recorded. BMO2 uses the January/February calendar year. BMO1-2026 was sat 19 November 2025 and is released.','copyright':'Statements are compact original paraphrases preserving mathematical conditions; linked official solutions remain on UKMT servers. Own solutions are original exposition.'}
